/**
 * Substitui o logo atual. O tipo é conferido pelo conteúdo do arquivo, não pela extensão.
 * @summary Envia o logo (campo "arquivo"): PNG, JPEG ou WEBP de até 2 MB
 */
export const enviarLogo = async (
  enviarLogoBody: EnviarLogoBody,
  options?: Parameters<typeof requisicao>[1],
): Promise<LogoResponse> => {
  const formData = new FormData();
  if (enviarLogoBody.arquivo !== undefined) {
    formData.append(`arquivo`, enviarLogoBody.arquivo);
  }

  return requisicao<LogoResponse>(getEnviarLogoUrl(), {
    ...options,
    method: 'POST',
    body: formData,
  });
};

